WITH cleaned AS (SELECT *, DATEDIFF(CURRENT_DATE(), started_at) AS days_since_started_at, COALESCE(browser, 'UNKNOWN') AS resolved_browser FROM sessions WHERE started_at > DATE '2023-08-30') SELECT d.segment, e.browser, COUNT(*) AS num_rows, MIN(e.days_since_started_at) AS min_days_since_started_at FROM cleaned e INNER JOIN customers d ON e.customer_id = d.id GROUP BY CUBE (d.segment, e.browser)
